xql_query:
// ============================================================
// Rule: AWS_Critical EC2 instances (Stop ou Terminate)
// Vendor: AWS
// Objective:
// Detect activity associated with AWS_Critical EC2 instances (Stop ou Terminate).
// Severity: SEV_040_HIGH
// Category: User Defined
// ============================================================
// SANITIZED: Environment-specific values replaced with generic placeholders.
// MITRE ATT&CK:
// Tactic: TA0042 - Resource Development
// Technique: T1584 - Compromise Infrastructure

// Configuração inicial: comparações não diferenciam maiúsculas/minúsculas
// Objetivo: reduzir risco de perda de eventos por variações de caixa em campos textuais (ex.: userAgent)
config case_sensitive = false

// Fonte de dados: logs brutos do AWS (CloudTrail)
// O dataset 'amazon_aws_raw' contém eventos de auditoria de serviços AWS, incluindo EC2.
| dataset = amazon_aws_raw

// Filtro: restringe aos eventos do serviço EC2
| filter eventSource = "ec2.amazonaws.com"

// Filtro: identifica ações críticas que interrompem disponibilidade
// - StopInstances: parada da instância
// - TerminateInstances: término/remoção definitiva da instância
| filter (eventName = "StopInstances" or eventName = "TerminateInstances")

// Converte responseElements para string para facilitar busca de instanceId no payload
// (útil quando o schema não expõe todos os instanceIds como campos separados)
| alter elements = to_json_string(responseElements)

// Filtro: mantém somente eventos que envolvam instâncias críticas (lista allowlist de instanceIds)
// Observação: manter como OR explícito evita falhas quando não há suporte a listas/arrays no filtro.
| filter
    elements contains "<EC2_INSTANCE_ID_1>" or
    elements contains "<EC2_INSTANCE_ID_2>" or
    elements contains "<EC2_INSTANCE_ID_3>" or
    elements contains "<EC2_INSTANCE_ID_4>" or
    elements contains "<EC2_INSTANCE_ID_5>" or
    elements contains "<EC2_INSTANCE_ID_6>" or
    elements contains "<EC2_INSTANCE_ID_7>" or
    elements contains "<EC2_INSTANCE_ID_8>" or
    elements contains "<EC2_INSTANCE_ID_9>" or
    elements contains "<EC2_INSTANCE_ID_10>" or
    elements contains "<EC2_INSTANCE_ID_11>" or
    elements contains "<EC2_INSTANCE_ID_12>" or
    elements contains "<EC2_INSTANCE_ID_13>" or
    elements contains "<EC2_INSTANCE_ID_14>" or
    elements contains "<EC2_INSTANCE_ID_15>" or
    elements contains "<EC2_INSTANCE_ID_16>" or
    elements contains "<EC2_INSTANCE_ID_17>" or
    elements contains "<EC2_INSTANCE_ID_18>"

// Extração: identifica o executor da ação (principalId do userIdentity)
// Isso ajuda a diferenciar console vs automação e facilita allowlist/exception.
| alter user_principal_id = to_json_string(useridentity) -> principalId

// Exclusão: ignora execuções esperadas por automações/agendadores conhecidos
// Observação: 'not in' aqui depende do parser aceitar curingas; se não funcionar,
// substitua por "not contains" com as strings.
| filter user_principal_id not in ("*<AUTOMATION_PRINCIPAL_1>*", "*<AUTOMATION_PRINCIPAL_2>*")

// Extração: captura o instanceId (primeiro item do instancesSet)
// Observação: em StopInstances/TerminateInstances podem existir múltiplas instâncias no mesmo evento;
// este caminho pega apenas o primeiro item. Se precisar de todos, dá para adaptar para values().
| alter instance_id = to_json_string(responseElements) -> instancesSet.items[0].instanceId

// Saída final: campos recomendados para alerta/correlação e auditoria
| fields
    _time,              // Timestamp no XSIAM
    eventTime,          // Timestamp original do CloudTrail
    eventName,          // Ação executada (StopInstances/TerminateInstances)
    user_principal_id,  // Executor (principalId)
    instance_id,        // Instância impactada (primeira do payload)
    userAgent,          // Origem (console/cli/sdk)
    userIdentity,       // Objeto completo do executor (evidência)
    responseElements,   // Detalhes da resposta (evidência)
    requestParameters   // Parâmetros (ex.: instanceIds solicitadas)
